export function initTheme() {
 const toggle = document.getElementById('theme-toggle');
 const root = document.documentElement;
 const saved = localStorage.getItem('em-theme') || 'dark';
 applyTheme(saved);
 if (toggle) {
 toggle.checked = saved === 'light';
 toggle.addEventListener('change', () => {
 const next = toggle.checked ? 'light' : 'dark';
 applyTheme(next);
 localStorage.setItem('em-theme', next);
 });
 }
 function applyTheme(theme) {
 root.setAttribute('data-theme', theme);
 if (toggle) toggle.checked = theme === 'light';
 }
}
export function initCursor() {
 const cursor = document.getElementById('cursor');
 const ring = document.getElementById('cursor-ring');
 if (!cursor || !ring) return;
 let mx = -100, my = -100;
 let rx = -100, ry = -100;
 document.addEventListener('mousemove', e => {
 mx = e.clientX;
 my = e.clientY;
 });
 document.addEventListener('mouseleave', () => {
 cursor.style.opacity = '0';
 ring.style.opacity = '0';
 });
 document.addEventListener('mouseenter', () => {
 cursor.style.opacity = '1';
 ring.style.opacity = '1';
 });
 (function animateCursor() {
 cursor.style.left = mx + 'px';
 cursor.style.top = my + 'px';
 rx += (mx - rx) * 0.12;
 ry += (my - ry) * 0.12;
 ring.style.left = rx + 'px';
 ring.style.top = ry + 'px';
 requestAnimationFrame(animateCursor);
 })();
}
export function initScrollReveal() {
 const revealEls = document.querySelectorAll('.reveal');
 if (!revealEls.length) return;
 const observer = new IntersectionObserver(
 entries => {
 entries.forEach(entry => {
 if (entry.isIntersecting) {
 entry.target.classList.add('visible');
 observer.unobserve(entry.target);
 }
 });
 },
 { threshold: 0.12, rootMargin: '0px 0px -40px 0px' }
 );
 revealEls.forEach(el => observer.observe(el));
}
export function initSmoothScroll() {
 document.querySelectorAll('a[href^="#"]').forEach(anchor => {
 anchor.addEventListener('click', e => {
 const target = document.querySelector(anchor.getAttribute('href'));
 if (!target) return;
 e.preventDefault();
 target.scrollIntoView({ behavior: 'smooth', block: 'start' });
 });
 });
}
export function initNav() {
 const nav = document.getElementById('nav');
 const toggle = document.getElementById('nav-toggle');
 const links = document.getElementById('nav-links');
 if (!nav) return;
 window.addEventListener('scroll', () => {
 nav.classList.toggle('scrolled', window.scrollY > 60);
 }, { passive: true });
 if (toggle && links) {
 toggle.addEventListener('click', () => {
 const isOpen = links.classList.contains('mobile-open');
 if (isOpen) {
 closeMenu();
 } else {
 openMenu();
 }
 });
 links.querySelectorAll('a').forEach(a => {
 a.addEventListener('click', closeMenu);
 });
 window.addEventListener('resize', () => {
 if (window.innerWidth > 900) {
 closeMenu(true); 
 }
 }, { passive: true });
 }
 function openMenu() {
 links.classList.add('mobile-open');
 toggle.classList.add('open');
 toggle.setAttribute('aria-expanded', 'true');
 document.body.style.overflow = 'hidden'; 
 }
 function closeMenu(silent = false) {
 links.classList.remove('mobile-open');
 toggle.classList.remove('open');
 toggle.setAttribute('aria-expanded', 'false');
 document.body.style.overflow = '';
 }
}
export function initHero() {
 initTextRotate();
 initFloating();
}
function initTextRotate() {
 const el = document.getElementById('text-rotate-el');
 if (!el) return;
 const words = [
 'beautiful',
 'fast',
 'accessible',
 'creative',
 'memorable',
 'unique',
 'responsive',
 'polished',
 'powerful',
 'pixel-perfect',
 ];
 let current = 0;
 let animating = false;
 renderWord(words[0], 'in');
 setInterval(() => {
 if (animating) return;
 const next = (current + 1) % words.length;
 exitWord(() => {
 current = next;
 renderWord(words[current], 'in');
 });
 }, 2800);
 function renderWord(word, direction) {
 animating = true;
 el.innerHTML = '';
 const chars = [...word]; 
 const totalChars = chars.length;
 chars.forEach((char, i) => {
 const span = document.createElement('span');
 span.className = 'tr-char';
 span.textContent = char === ' ' ? '\u00A0' : char;
 const delay = (totalChars - 1 - i) * 30;
 span.style.cssText = `
 display: inline-block;
 transform: translateY(100%);
 opacity: 0;
 transition:
 transform ${380 + delay}ms cubic-bezier(0.34, 1.56, 0.64, 1) ${delay}ms,
 opacity ${280}ms ease ${delay}ms;
 `;
 el.appendChild(span);
 requestAnimationFrame(() => requestAnimationFrame(() => {
 span.style.transform = 'translateY(0)';
 span.style.opacity = '1';
 }));
 });
 const lastDelay = (totalChars - 1) * 30 + 400;
 setTimeout(() => { animating = false; }, lastDelay);
 }
 function exitWord(callback) {
 animating = true;
 const chars = el.querySelectorAll('.tr-char');
 const total = chars.length;
 chars.forEach((span, i) => {
 const delay = i * 25; 
 span.style.transition = `
 transform ${300}ms cubic-bezier(0.22, 1, 0.36, 1) ${delay}ms,
 opacity ${200}ms ease ${delay}ms
 `;
 span.style.transform = 'translateY(-120%)';
 span.style.opacity = '0';
 });
 const exitDuration = total * 25 + 320;
 setTimeout(callback, exitDuration);
 }
}
function initFloating() {
 const hero = document.getElementById('hero');
 const imgs = document.querySelectorAll('.fl-img');
 if (!hero || !imgs.length) return;
 const positions = Array.from(imgs).map(() => ({ x: 0, y: 0 }));
 let targetX = 0;
 let targetY = 0;
 let heroRect = hero.getBoundingClientRect();
 window.addEventListener('resize', () => {
 heroRect = hero.getBoundingClientRect();
 }, { passive: true });
 hero.addEventListener('mousemove', (e) => {
 targetX = (e.clientX - heroRect.left - heroRect.width / 2) / (heroRect.width / 2);
 targetY = (e.clientY - heroRect.top - heroRect.height / 2) / (heroRect.height / 2);
 }, { passive: true });
 hero.addEventListener('mouseleave', () => {
 targetX = 0;
 targetY = 0;
 });
 hero.addEventListener('touchmove', (e) => {
 const t = e.touches[0];
 targetX = (t.clientX - heroRect.left - heroRect.width / 2) / (heroRect.width / 2);
 targetY = (t.clientY - heroRect.top - heroRect.height / 2) / (heroRect.height / 2);
 }, { passive: true });
 const SENSITIVITY = 40; 
 const EASE = 0.06;
 function lerp(a, b, t) { return a + (b - a) * t; }
 function animate() {
 imgs.forEach((img, i) => {
 const depth = parseFloat(img.dataset.depth || '1');
 const maxShift = SENSITIVITY * depth * -0.5; 
 const tx = targetX * maxShift;
 const ty = targetY * maxShift;
 positions[i].x = lerp(positions[i].x, tx, EASE);
 positions[i].y = lerp(positions[i].y, ty, EASE);
 img.style.transform = `translate3d(${positions[i].x}px, ${positions[i].y}px, 0)`;
 });
 requestAnimationFrame(animate);
 }
 imgs.forEach((img, i) => {
 img.style.setProperty('--fl-delay', `${0.4 + i * 0.15}s`);
 requestAnimationFrame(() => requestAnimationFrame(() => {
 img.classList.add('fl-visible');
 }));
 });
 animate();
}
export function initForm() {
 const form = document.getElementById('contact-form');
 if (!form) return;
 form.addEventListener('submit', (e) => {
 e.preventDefault();
 const btn = form.querySelector('.form-submit');
 const fb = document.getElementById('form-feedback');
 if (!btn || !fb) return;
 btn.classList.add('loading');
 btn.disabled = true;
 setTimeout(() => {
 btn.classList.remove('loading');
 btn.disabled = false;
 fb.textContent = "✓ Message sent! I'll get back to you within 24 hours.";
 fb.className = 'form-feedback success';
 form.reset();
 setTimeout(() => {
 fb.textContent = '';
 fb.className = 'form-feedback';
 }, 5000);
 }, 1500);
 });
}
import { initCursor } from './cursor.js';
import { initScrollReveal, initSmoothScroll } from './scroll.js';
import { initNav } from './nav.js';
import { initTheme } from './theme.js';
import { initHero } from './hero.js';
import { initForm } from './form.js';
document.addEventListener('DOMContentLoaded', () => {
 initTheme();
 initHero();
 initCursor();
 initScrollReveal();
 initSmoothScroll();
 initNav();
 initForm();
});